import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:kuron_special/src/comix/comix_cipher.dart';

// Known-answer vectors generated by informations/bugs/comix/proof/cipher.py
// (exact port reference) using the live-captured cipher material below.
void main() {
  late CipherMaterial material;

  setUpAll(() {
    material = CipherMaterial.fromJson(
      jsonDecode(_materialJson) as Map<String, dynamic>,
    );
  });

  test('captured material is valid per Cipher.kt isValid', () {
    expect(material.isValid, isTrue);
    expect(
      const CipherMaterial(sboxes: [], keys: []).isValid,
      isFalse,
    );
    expect(
      CipherMaterial(
        sboxes: List.generate(3, (_) => List.filled(255, 0)),
        keys: material.keys,
      ).isValid,
      isFalse,
    );
    expect(
      () => ComixCipher(const CipherMaterial(sboxes: [], keys: [])),
      throwsArgumentError,
    );
  });

  test('sign matches python reference (captured material)', () {
    final cipher = ComixCipher(material);
    expect(
      cipher.sign('/api/v1/manga', 'content_rating[0]=safe&limit=28'),
      'IZ-P1pUtzmGC9ME_WcBCRiLDNHDO6fb2Y6YJ9IZE3fLmUvoUv20',
    );
    expect(cipher.sign('/api/v1/x', ''), 'IRE');
  });

  test('decrypt matches python reference (captured material)', () {
    final cipher = ComixCipher(material);
    expect(
      cipher.decrypt(
        'fkttOlFk6VX0vcYihoIit4uoThZoJj7kRa-P-OZ0e-CMDDUJVJQ',
      ),
      '{"result":{"items":[{"hid":"n93ny"}]}}',
    );
  });

  test('canonicalEntries matches Comix.kt rules', () {
    final entries = ComixCipher.canonicalEntries({
      'limit': ['28'],
      'content_rating': ['safe', 'suggestive'],
      'authors[]': ['1', '2'],
      'page': ['3'],
    });
    expect(
      entries.map((e) => '${e.key}=${e.value}').toList(),
      [
        'authors[0]=1',
        'authors[1]=2',
        'content_rating[0]=safe',
        'content_rating[1]=suggestive',
        'limit=28',
        'page=3',
      ],
    );
  });

  test('WebViewCapture parses payload + material', () {
    final raw = jsonDecode(_materialJson) as Map<String, dynamic>;
    final capture = WebViewCapture.fromJson({
      'payload': '{"result":{}}',
      'material': raw,
    });
    expect(capture.payload, '{"result":{}}');
    expect(capture.material!.isValid, isTrue);
    expect(WebViewCapture.fromJson({'payload': 'x'}).material, isNull);
  });
}

